import re
from pathlib import Path
out=Path('/app/output')
errors=[]
for p in out.glob('*.html'):
    text=p.read_text()
    ids=set(re.findall(r'id="([^"]+)"', text))
    for href in re.findall(r'href="([^"]+)"', text):
        if href.startswith('#') and href != '#':
            if href[1:] not in ids: errors.append(f'{p.name}: missing anchor {href}')
        elif '.html' in href:
            file, _, anchor=href.partition('#')
            target=out/file
            if not target.exists(): errors.append(f'{p.name}: missing file {file}')
            elif anchor and anchor not in set(re.findall(r'id="([^"]+)"', target.read_text())):
                errors.append(f'{p.name}: {href} missing target anchor')
print('errors:', errors or 'none')
# interaction sanity
for p in ['store.html','shop-laptops.html','shop-tablets.html']:
